# ──────────────────────────────────────────────────────────────────────────────
# 2) POMOCNÉ FUNKCIE
# ──────────────────────────────────────────────────────────────────────────────

def ensure_images_dir(path: str) -> None:
    os.makedirs(path, exist_ok=True)

def sanitize_filename(name: str) -> str:
    """
    Minimalistická sanitácia názvu súboru (VIN) pre súborový systém.
    VINy zvyknú byť OK, ale pre istotu vyhodiť nebezpečné znaky.
    """
    bad = '<>:"/\\|?*'
    for ch in bad:
        name = name.replace(ch, "_")
    # Orež whitespace
    return name.strip()

def unsplash_search(query: str, needed: int, client_id: str) -> list:
    """
    Získa aspoň `needed` výsledkov z Unsplash search API (agreguje stránky).
    per_page max 30 → stránkuje.
    Vracia list JSON objektov (položiek results).
    """
    collected = []
    page = 1
    per_page = 30  # maximum allowed by Unsplash
    total_pages_needed = math.ceil(needed / per_page)

    while len(collected) < needed and page <= total_pages_needed:
        url = (
            "https://api.unsplash.com/search/photos"
            f"?query={quote(query)}&page={page}&per_page={per_page}"
        )
        headers = {
            "Authorization": f"Client-ID {client_id}",
            "Accept-Version": "v1",
        }
        r = requests.get(url, headers=headers, timeout=30)
        if r.status_code != 200:
            print(f"❌ Unsplash search error ({query}) page {page}: {r.text}")
            break

        data = r.json()
        results = data.get("results", []) or []
        collected.extend(results)

        page += 1
        if REQUESTS_SLEEP_SECS:
            time.sleep(REQUESTS_SLEEP_SECS)

        # Ak výsledkov prišlo menej než per_page, ďalšia stránka zrejme už nič neprinesie
        if len(results) < per_page:
            break

    return collected[:needed]

def download_image(url: str, out_path: str) -> bool:
    """
    Stiahne obrázok a uloží do out_path. Vracia True/False podľa úspechu.
    """
    try:
        with requests.get(url, stream=True, timeout=60) as r:
            if r.status_code != 200:
                print(f"   ❌ HTTP {r.status_code} pri sťahovaní: {url}")
                return False
            content_type = r.headers.get("Content-Type", "")
            if "image" not in content_type:
                print(f"   ❌ Neobrázkový content-type ({content_type}): {url}")
                return False
            with open(out_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=1024 * 64):
                    if chunk:
                        f.write(chunk)
        return True
    except Exception as e:
        print(f"   ❌ Chyba pri sťahovaní {url}: {e}")
        return False

def fetch_images_for_query(query: str, count: int, client_id: str) -> list:
    """
    Pokúsi sa získať `count` obrázkov pre daný query.
    Ak nestačí, doplní chýbajúce kusy fallbackom prvym slovom z query.
    Vracia list URL adries (prioritne 'urls' -> 'regular').
    """
    items = unsplash_search(query + " car", count, client_id)
    urls = [it["urls"]["regular"] for it in items if it.get("urls", {}).get("regular")]

    if len(urls) < count:
        missing = count - len(urls)
        first_word = query.split()[0] if query else "car"
        print(f"   ⚠️ Pre '{query}' chýba {missing} obrázkov, doplním fallback '{first_word}'.")
        fb = unsplash_search(first_word + " car", missing, client_id)
        urls.extend([it["urls"]["regular"] for it in fb if it.get("urls", {}).get("regular")])

    # orez na požadovaný počet
    return urls[:count]

# ──────────────────────────────────────────────────────────────────────────────
# 3) HLAVNÁ LOGIKA
# ──────────────────────────────────────────────────────────────────────────────

def main():
    if not UNSPLASH_ACCESS_KEY or UNSPLASH_ACCESS_KEY.startswith("TU_VLOZ"):
        raise RuntimeError("Prosím vlož platný UNSPLASH_ACCESS_KEY.")

    ensure_images_dir(IMAGES_DIR)

    total_pairs = len(cars)
    print(f"🔎 Počet párov (značka+model): {total_pairs}")

    for idx, (label, vins) in enumerate(cars.items(), start=1):
        needed = len(vins)
        if needed == 0:
            continue

        print(f"\n[{idx}/{total_pairs}] ➜ '{label}' — potrebujem {needed} obrázkov")

        # 1 dotaz (prípadne viac stránok) na daný label
        urls = fetch_images_for_query(label, needed, UNSPLASH_ACCESS_KEY)

        if not urls:
            print(f"   ❌ Pre '{label}' sa nepodarilo získať žiadny obrázok (ani fallback).")
            continue

        # Mapovanie: i-ty VIN ↔ i-ty URL (poradie zoznamu)
        for vin, url in zip(vins, urls):
            safe_vin = sanitize_filename(str(vin))
            out_path = os.path.join(IMAGES_DIR, f"{safe_vin}.jpg")

            ok = download_image(url, out_path)
            if ok:
                print(f"   ✔ Uložené: {out_path}")
            else:
                print(f"   ❌ Nepodarilo sa uložiť VIN {vin} z URL: {url}")

        # Ak by bolo viac VINov než URL (extrémny nedostatok výsledkov), upozorni:
        if len(urls) < needed:
            print(f"   ⚠️ Pozor: pre '{label}' som našiel len {len(urls)}/{needed} obrázkov.")

    print("\n✅ HOTOVO — obrázky uložené do priečinka ./images/ ako <VIN>.jpg")

if __name__ == "__main__":
    main()
